// Extract incoming delay & transit disruption event
const body = $input.first().json.body || $input.first().json;
const trainNumber = body.train_number || '12301';
const trainName = body.train_name || 'Rajdhani Express';
const delayMinutes = body.delay_minutes || 45;
const station = body.current_station || 'NDLS';
const PNR = body.pnr || 'TRV-89412';
const user = body.user || {};

const prompt = `You are TravelIQ Real-Time Transit Recovery Assistant.
Traveler: ${user.name || 'Traveler'}
Train: #${trainNumber} (${trainName})
Current Delay: ${delayMinutes} minutes at ${station}
PNR: ${PNR}

Generate an immediate 3-step advisory:
1. Empathetic delay update explaining impact on arrival time.
2. Refund Rights & TDR Policy (e.g. Full refund option if delay exceeds 3 hours).
3. Alternative connecting train / metro option recommendation.`;

return {
  json: {
    pnr: PNR,
    train_number: trainNumber,
    train_name: trainName,
    delay_minutes: delayMinutes,
    current_station: station,
    user_name: user.name || 'Traveler',
    user_email: user.email,
    callback_url: body.callback_url || 'http://localhost:5000/api/n8n/delay-alert',
    secret: body.secret || 'traveliq_n8n_secret_token_2026',
    ai_prompt: prompt
  }
};

// Generate AI Delay & Refund Advisory
const data = $input.first().json;
const delayHrs = Math.floor(data.delay_minutes / 60);
const delayMins = data.delay_minutes % 60;
const timeStr = delayHrs > 0 ? `${delayHrs}h ${delayMins}m` : `${delayMins} minutes`;

const advisory = `⚠️ Transit Update for Train #${data.train_number} (${data.train_name})

Hello ${data.user_name}, your train is currently running delayed by ${timeStr} near ${data.current_station}.

🤖 AI Recovery Plan & Policies:
• Arrival Estimate: Updated expected arrival re-calculated with signal priority optimization.
• Refund Eligibility: If delay exceeds 3 hours, full ticket refund without cancellation fee is available via 1-click TDR in your TravelIQ app.
• Pantry & Amenities: Station executive lounge access and complimentary refreshments apply for delays over 2 hours.

Need rerouting? Tap 'Smart Re-route' in your app!`;

return {
  json: {
    ...data,
    title: `Delay Alert: Train #${data.train_number} (+${timeStr})`,
    ai_advisory: advisory
  }
};

